import {readDoorAnimations} from './door-animation.js';
import {nativeDoorWorkshop} from './door-animation-ui.js';
import{facingSelect}from'./link-ui.js';
import{gateLocal}from'./gate-cells.js';
import{uid,newMap,inBounds}from'./model.js';
import{buildRoom}from'./smart-model.js';
import{addPortal,portalAt,setMovement,movementAt}from'./world-model.js';
import{fieldAt,ledgeAt}from'./field-model.js';
export function doorWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={styleId:null,pending:null,query:''};
 const nativeDoors=nativeDoorWorkshop(api);
 const styles=()=>api.smart().prefabs().filter(p=>p.portalKind||p.category?.startsWith('Doors'));
 const links=()=>api.project().links.filter(l=>l.runtime?.type==='portal');
 function open(){api.modal('Doors & portals',`<p>Place an entrance, choose its destination map, then tap the arrival tile. A return link is included by default.</p><div class="smart-actions"><button id="doorLinkTiles" type="button" class="primary">Link existing doorway tiles</button><button id="doorCancelPending" type="button">Cancel unfinished link</button></div><label>Find doorway art<input id="doorSearch" type="search" placeholder="Door, stairs, ladder, cave…"></label><div id="doorStyles" class="smart-cards"></div><button id="nativeDoorFrames" type="button">Edit native door frames</button><h3>Linked entrances</h3><div id="doorLinks"></div><p class="hint-line">The portal activates when stepped on. Native map-to-map travel is written into the edited ROM. Choose opening frames in an entrance’s Edit panel.</p>`);$('#nativeDoorFrames').onclick=nativeDoors.open;$('#doorLinkTiles').onclick=()=>begin(null);$('#doorCancelPending').onclick=()=>{state.pending=null;api.mode('move');api.close();};$('#doorSearch').oninput=e=>{state.query=e.target.value;cards();};cards();$('#doorLinks').innerHTML=links().map(l=>{const a=api.project().maps.find(m=>m.id===l.from.mapId),b=api.project().maps.find(m=>m.id===l.to.mapId);return`<div class="world-row"><span><b>${esc(l.label||'Entrance')}</b><small>${esc(a?.name)} ${l.twoWay?'↔':'→'} ${esc(b?.name)}</small></span><button type="button" data-door-edit="${esc(l.id)}">Edit</button></div>`;}).join('')||'<p>No authored portals yet.</p>';document.querySelectorAll('[data-door-edit]').forEach(b=>b.onclick=()=>edit(links().find(l=>l.id===b.dataset.doorEdit)));}
 function cards(){$('#doorStyles').innerHTML=styles().filter(p=>(p.name+' '+p.category+' '+(p.tags||'')).toLowerCase().includes(state.query.toLowerCase())).map(p=>{const a=api.asset(p.assetId);return`<article class="smart-card"><svg class="smart-thumb" viewBox="${p.sx||0} ${p.sy||0} ${p.sw||a.width} ${p.sh||a.height}"><image href="${esc(a.data||a.src)}" width="${a.width}" height="${a.height}"/></svg><strong>${esc(p.name)}</strong><small>${p.w} × ${p.h} tiles</small><button data-door-style="${esc(p.id)}" type="button">Place & link</button></article>`;}).join('');document.querySelectorAll('[data-door-style]').forEach(b=>b.onclick=()=>begin(b.dataset.doorStyle));}
 function begin(styleId){state.styleId=styleId;state.pending=null;api.mode('door');api.close();api.toast('1 of 3 · Tap the entrance tile.');}
 function check(map,x,y){if(!inBounds(map,x,y)||fieldAt(map,x,y)||ledgeAt(map,x,y)||map.gates?.some(g=>gateLocal(g,x,y))||map.markers.some(n=>n.runtime?.enabled!==false&&n.runtime?.trigger==='step'&&n.x===x&&n.y===y))throw Error('Choose a tile away from HM objects, ledges, gates and step events.');}
 function artFits(map,p,style){if(!style)return;const e=style.portalAnchor||{x:0,y:style.h-1},x=p.x-e.x,y=p.y-e.y;if(x<0||y<0||x+style.w>map.width||y+style.h>map.height)throw Error('Leave room above and beside the entrance for the full doorway.');}
 function tap(x,y){try{const map=api.map();check(map,x,y);if(state.pending){if(state.pending.target!==map.id)throw Error('Choose the arrival on the selected destination map.');finish({mapId:map.id,x,y});return;}const existing=portalAt(api.project(),map.id,x,y);if(existing){edit(existing.link);return;}const style=styles().find(p=>p.id===state.styleId);artFits(map,{x,y},style);state.pending={from:{mapId:map.id,x,y},styleId:style?.id};destination();}catch(e){api.error(e);}}
 function destination(){const p=state.pending;if(!p)return;api.modal('2 of 3 · Choose the destination',`<p>Entrance: <b>${esc(api.project().maps.find(m=>m.id===p.from.mapId)?.name)}</b>. Pick the other map, then tap exactly where the player arrives.</p><label>Entrance name<input id="doorName" maxlength="80" value="${esc(p.label||styles().find(s=>s.id===p.styleId)?.name||'Doorway')}"></label><label>Destination<select id="doorDestination"><option value="new">Create a new room</option>${api.project().maps.map(m=>`<option value="${esc(m.id)}" ${m.id!==p.from.mapId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label class="check"><input id="doorReturn" type="checkbox" ${p.twoWay!==false?'checked':''}> Link the return trip too</label><div id="doorNewRoom" hidden><label>Floor & wallpaper<select id="doorRoomTheme">${api.smart().rooms().map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><div class="field-row"><label>Room width<input id="doorRoomW" type="number" min="8" max="64" value="16"></label><label>Room height<input id="doorRoomH" type="number" min="8" max="64" value="14"></label></div></div>`,()=>{p.label=$('#doorName').value.trim()||'Doorway';p.twoWay=$('#doorReturn').checked;if($('#doorDestination').value==='new'){createRoom();return false;}p.target=$('#doorDestination').value;api.loadMap(p.target);api.mode('doorTarget');api.close();api.toast('3 of 3 · Tap the arrival tile.');},'Choose arrival');$('#doorDestination').onchange=()=>$('#doorNewRoom').hidden=$('#doorDestination').value!=='new';$('#doorDestination').onchange();}
 function createRoom(){const p=state.pending,w=+$('#doorRoomW').value,h=+$('#doorRoomH').value,theme=api.smart().rooms().find(t=>t.id===$('#doorRoomTheme').value),project=api.project();if(![w,h].every(n=>Number.isInteger(n)&&n>=8&&n<=64))throw Error('Choose whole room sizes from 8 to 64 tiles.');if(project.maps.length>=80||project.maps.reduce((n,m)=>n+m.width*m.height,0)+w*h>400000)throw Error('This room exceeds the project limit.');const source=project.maps.find(m=>m.id===p.from.mapId),room=newMap(p.label+' · inside',w,h);room.world={x:source.world.x+280,y:source.world.y};room.rom={sourceId:source.rom?.sourceId||null,generated:true,interiorKind:'house',originalWidth:0,originalHeight:0,originalBlocks:[]};room.generator={type:'door-room',exteriorId:source.id};buildRoom(room,{x1:0,y1:0,x2:w-1,y2:h-1},theme);for(let y=0;y<h;y++)for(let x=0;x<w;x++)setMovement(room,x,y,{mode:x===0||x===w-1||y<(theme.wall.rows||3)||y===h-1?'block':'walk',elevation:3});const to={mapId:room.id,x:Math.floor(w/2),y:h-1};setMovement(room,to.x,to.y,{mode:'walk',elevation:3});api.change(()=>{api.library.attach(project,'roomStyles',theme);project.maps.push(room);commit(to);});state.pending=null;api.close();api.loadMap(room.id);api.mode('move');api.refresh();api.toast('Room, entrance and return portal created.');}
 function finish(to){const p=state.pending;const fromMap=api.project().maps.find(m=>m.id===p.from.mapId);if(to.mapId===p.from.mapId&&to.x===p.from.x&&to.y===p.from.y)throw Error('Choose a different arrival tile.');if(portalAt(api.project(),to.mapId,to.x,to.y)?.link.id!==p.replaceId&&portalAt(api.project(),to.mapId,to.x,to.y))throw Error('This tile already belongs to a portal. Choose a free arrival.');api.modal('Link these entrances',`<p><b>${esc(fromMap.name)}</b> ${p.twoWay?'↔':'→'} <b>${esc(api.map().name)}</b></p><p>Step onto the entrance to travel. ${p.twoWay?'The other tile brings you back.':''}</p><label>Face on arrival${facingSelect('doorArrivalFacing',p.arrivalFacing)}</label><label>Face on return${facingSelect('doorReturnFacing',p.returnFacing)}</label><label class="check"><input id="doorArrivalArt" type="checkbox"> Place the same doorway art at the arrival too</label>`,()=>{const style=styles().find(s=>s.id===p.styleId);if($('#doorArrivalArt').checked)artFits(api.map(),to,style);p.arrivalFacing=$('#doorArrivalFacing').value;p.returnFacing=$('#doorReturnFacing').value;api.change(()=>commit(to,$('#doorArrivalArt').checked));state.pending=null;api.mode('move');api.refresh();api.toast('Entrance linked. Try Quick check or Play edited ROM.');},'Link entrances');}
 function commit(to,arrivalArt=false){const p=state.pending,project=api.project(),style=styles().find(s=>s.id===p.styleId);for(const end of[p.from,...(arrivalArt?[to]:[])]){const map=project.maps.find(m=>m.id===end.mapId);if(style&&map.objects.length>=5000)throw Error('This map has too many objects.');}let link=project.links.find(l=>l.id===p.replaceId);if(link){Object.assign(link,{from:{...p.from},to:{...to},twoWay:p.twoWay,label:p.label});for(const map of project.maps)map.objects=map.objects.filter(o=>o.portalId!==link.id||o.portalEnd!=='to');}else link=addPortal(project,p.from,to,{twoWay:p.twoWay,label:p.label,style:'step'});link.runtime={...link.runtime,type:'portal',style:link.runtime?.style||'step',arrivalFacing:p.arrivalFacing||'auto',returnFacing:p.returnFacing||'auto'};for(const end of[p.from,to]){const m=project.maps.find(m=>m.id===end.mapId);setMovement(m,end.x,end.y,{mode:'walk',elevation:3});if(m.wallCells)m.wallCells[end.y*m.width+end.x]=null;}if(style){api.library.attach(project,'prefabs',style);if(!project.maps.some(m=>m.objects.some(o=>o.portalId===link.id&&o.portalEnd==='from')))placeArt(project.maps.find(m=>m.id===p.from.mapId),p.from,style,link.id,'from');if(arrivalArt)placeArt(project.maps.find(m=>m.id===to.mapId),to,style,link.id,'to');}return link;}
 function placeArt(map,end,style,portalId,portalEnd){const a=api.asset(style.assetId),anchor=style.portalAnchor||{x:0,y:style.h-1};map.objects.push({id:uid(),assetId:a.id,name:style.name,sx:style.sx||0,sy:style.sy||0,sw:style.sw||a.width,sh:style.sh||a.height,x:end.x-anchor.x,y:end.y-anchor.y,w:style.w,h:style.h,collisionChoice:style.movementMask?'mask':'keep',...(style.movementMask?{collisionMask:structuredClone(style.movementMask)}:{}),prefabId:style.id,portalId,portalEnd,portalAnchor:anchor});}
 function syncObject(o){const l=links().find(l=>l.id===o.portalId);if(l)Object.assign(l[o.portalEnd||'from'],{x:Math.round(o.x+(o.portalAnchor?.x||0)),y:Math.round(o.y+(o.portalAnchor?.y||0))});}
 function syncArt(l){for(const map of api.project().maps)for(const o of map.objects.filter(o=>o.portalId===l.id)){const p=l[o.portalEnd||'from'];o.x=p.x-(o.portalAnchor?.x||0);o.y=p.y-(o.portalAnchor?.y||0);}}
 function edit(l){const p=api.project(),mapName=id=>p.maps.find(m=>m.id===id)?.name;let nativeStyles=[];try{const session=api.session();if(session)nativeStyles=[...readDoorAnimations(session.reader,session.id).doors,...Object.entries(p.doorAnimations?.[session.id]?.doors||{}).filter(([id])=>+id>=32).map(([id,row])=>({...row,id:+id}))];}catch{}const animationSelect=(id,value)=>`<select id="${id}"><option value="">Automatic native style</option>${nativeStyles.map(s=>`<option value="${s.id}" ${s.id===value?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`;api.modal('Edit '+(l.label||'entrance'),`<label>Name<input id="editDoorName" maxlength="80" value="${esc(l.label)}"></label><p>${esc(mapName(l.from.mapId))} ${l.twoWay?'↔':'→'} ${esc(mapName(l.to.mapId))}</p><label class="check"><input id="editDoorReturn" type="checkbox" ${l.twoWay?'checked':''}> Return trip enabled</label><label>Face on arrival${facingSelect('editDoorArrivalFacing',l.runtime?.arrivalFacing)}</label><label>Face on return${facingSelect('editDoorReturnFacing',l.runtime?.returnFacing)}</label>${nativeStyles.length?`<label>Entrance animation${animationSelect('editDoorNative',l.runtime?.nativeDoorStyle)}</label><label>Return animation${animationSelect('editDoorNativeReturn',l.runtime?.nativeReturnDoorStyle)}</label><p class="hint-line">Chosen frames are registered against the exported doorway metatile. Paint shared styles in Native door frames.</p>`:''}<div class="smart-actions"><button id="visitDoorFrom" type="button">Open entrance map</button><button id="visitDoorTo" type="button">Open arrival map</button><button id="retargetDoor" type="button">Choose a new destination</button><button id="removeDoor" type="button" class="danger">Remove portal</button></div>`,()=>{api.change(()=>{l.label=$('#editDoorName').value.trim()||'Entrance';l.twoWay=$('#editDoorReturn').checked;l.runtime={...l.runtime,type:'portal',style:l.runtime?.style||'step',arrivalFacing:$('#editDoorArrivalFacing').value,returnFacing:$('#editDoorReturnFacing').value};for(const [id,key]of [['editDoorNative','nativeDoorStyle'],['editDoorNativeReturn','nativeReturnDoorStyle']]){const value=$('#'+id)?.value;if(value!==undefined&&value!==''){l.runtime[key]=+value;l.runtime.style='door';}else delete l.runtime[key];}});api.refresh();},'Save entrance');$('#visitDoorFrom').onclick=()=>{api.close();api.loadMap(l.from.mapId);};$('#visitDoorTo').onclick=()=>{api.close();api.loadMap(l.to.mapId);};$('#removeDoor').onclick=()=>{api.change(()=>{p.links=p.links.filter(v=>v.id!==l.id);for(const m of p.maps)m.objects=m.objects.filter(o=>o.portalId!==l.id);});api.close();api.refresh();};$('#retargetDoor').onclick=()=>{state.pending={from:{...l.from},label:l.label,twoWay:l.twoWay,styleId:p.maps.flatMap(m=>m.objects).find(o=>o.portalId===l.id&&o.portalEnd==='from')?.prefabId,replaceId:l.id,arrivalFacing:l.runtime?.arrivalFacing,returnFacing:l.runtime?.returnFacing};destination();};}
 return{state,styles,open,begin,tap,edit,syncObject,syncArt};
}
